/**
 * @name Path traversal in archive extraction
 * @description Extracting archives without validating member paths can allow writing files outside the intended directory
 * @kind path-problem
 * @problem.severity error
 * @id py/setuptools-path-traversal-archive
 * @tags security
 *        external/cwe/cwe-22
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      // TarFile member names
      call = API::moduleImport("tarfile").getMember("TarFile").getMember(["getmembers", "getnames"]).getACall() or
      call = API::moduleImport("tarfile").getMember("open").getReturn().getMember(["getmembers", "getnames"]).getACall() or
      // ZipFile member names
      call = API::moduleImport("zipfile").getMember("ZipFile").getMember(["namelist", "infolist"]).getACall() or
      // Individual member name access
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = "name"
      |
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // File operations that write to paths
      call = API::moduleImport("tarfile").getMember("TarFile").getMember(["extract", "extractall"]).getACall() or
      call = API::moduleImport("zipfile").getMember("ZipFile").getMember(["extract", "extractall"]).getACall() or
      call = API::builtin("open").getACall()
      |
      sink = call.getArg(_) or sink = call.getArgByName(_)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from archive member $@.", source.getNode(), "name"
